// ----- tessellate
const D=c.getImageData(0,0,CW*TS,CH*TS).data;
const keys=Object.keys(P),rgb=keys.map(k=>{const n=parseInt(P[k].slice(1),16);return [n>>16,(n>>8)&255,n&255];});
const out=document.createElement('canvas');out.width=1080;out.height=1920;
const o=out.getContext('2d');
o.fillStyle='#1c150f';o.fillRect(0,0,1080,1920); // grout
let seed=5;const R=()=>{seed=(seed*16807)%2147483647;return seed/2147483647;};
const tint=(rg,k,gold)=>{ // lightness jitter
 const j=(R()-.5)*(gold?.34:.2);
 let r=rg[0],g=rg[1],b=rg[2];
 const f=1+j; r=Math.min(255,r*f);g=Math.min(255,g*f);b=Math.min(255,b*f);
 if(gold&&R()<.08){r=255;g=232;b=140;}
 return `rgb(${r|0},${g|0},${b|0})`;
};
for(let cy=0;cy<CH;cy++)for(let cx=0;cx<CW;cx++){
 const i=((cy*TS+TS/2|0)*CW*TS+(cx*TS+TS/2|0))*4;
 const a=[D[i],D[i+1],D[i+2]];
 let best=0,bd=1e9;rgb.forEach((q,k)=>{const d=(q[0]-a[0])**2+(q[1]-a[1])**2+(q[2]-a[2])**2;if(d<bd){bd=d;best=k;}});
 const key=keys[best],gold=key=='gold'||key=='goldL';
 const x=cx*TS+TS/2,y=cy*TS+TS/2,rot=(R()-.5)*.28,s=TS-1.8-R()*1.2;
 o.save();o.translate(x+(R()-.5)*1.2,y+(R()-.5)*1.2);o.rotate(rot);
 o.fillStyle=tint(rgb[best],key,gold);
 o.beginPath();o.roundRect(-s/2,-s/2,s,s,1.2);o.fill();
 // top-left bevel highlight
 o.fillStyle=gold?'rgba(255,240,170,.5)':'rgba(255,255,255,.16)';o.fillRect(-s/2,-s/2,s,1.4);
 o.fillStyle='rgba(0,0,0,.18)';o.fillRect(-s/2,s/2-1.2,s,1.2);
 o.restore();
}
